import 'package:cephalopod/features/home/presentation/models/saved_game_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'home_view_state.freezed.dart';

/// What Home shows that can change: the saved game to continue
/// ([savedGame]), if there is one, so Home offers Continue, and whether Home
/// should open How to play by itself ([showHowToPlay]), as it does on the
/// first launch.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class HomeViewState with _$HomeViewState {
  const factory HomeViewState({
    SavedGameUi? savedGame,
    @Default(false) bool showHowToPlay,
  }) = _HomeViewState;
}
